"""Package original physical-error concept plates without changing the museum."""
from pathlib import Path
from html import escape as e
from html.parser import HTMLParser
from urllib.parse import urlsplit
import json, shutil, struct, zipfile

OUT=Path(__file__).resolve().parent
data=json.loads((OUT/'atlas.json').read_text(encoding='utf-8'))
(OUT/'images').mkdir(exist_ok=True)
dimensions={}
for plate in data['plates']:
    source=Path(plate['source_path']); target=OUT/plate['saved_file']
    if source.exists(): shutil.copy2(source,target)
    raw=target.read_bytes()
    assert raw[:8]==b'\x89PNG\r\n\x1a\n'
    dimensions[plate['id']]=struct.unpack('>II',raw[16:24])

thumbs=''.join(f'<a href="#{p["id"]}"><img src="{p["saved_file"]}" alt="{e(p["title"])}"><span>{e(p["title"])}</span></a>' for p in data['plates'])
sections=''
for p in data['plates']:
    w,h=dimensions[p['id']]
    notes=''
    for item in p['items']:
        notes+=f'<article><h3>{e(item["label"])}</h3><p class="caption">{e(item["caption"])}</p><p>{e(item["situation"])}</p><details><summary>The concept behind the image</summary><p>{e(item["meaning"])}</p></details></article>'
    sections+=f'<section id="{p["id"]}" class="plate"><div><p class="eyebrow">{e(p["family"])}</p><h2>{e(p["title"])}</h2><figure><a href="{p["saved_file"]}"><img loading="lazy" src="{p["saved_file"]}" width="{w}" height="{h}" alt="{e(p["title"]+": "+", ".join(i["label"] for i in p["items"]))}"></a><figcaption>Original AI-generated concept plate · open image for full size</figcaption></figure></div><div class="notes">{notes}</div></section>'

html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The dark side of The Nature of Code — Endless Museum</title><style>
:root{--paper:#eee9df;--ink:#242321;--muted:#6c665e;--line:#cac2b5;--red:#842f31}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,sans-serif}a{color:var(--red);text-underline-offset:4px}header,main,footer{max-width:1480px;padding:38px;margin:auto}header{padding-top:75px}h1,h2,h3{font-family:Georgia,serif;line-height:1.1}h1{font-size:clamp(42px,6.8vw,94px);max-width:1140px;letter-spacing:-.045em;margin:20px 0 30px}h1 em{font-weight:400}h2{font-size:36px;margin:12px 0 24px}h3{font-size:19px;margin:0 0 10px}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-weight:750;color:var(--red);font-size:11px}.lead{font:26px/1.5 Georgia,serif;max-width:870px}.small,figcaption{font-size:13px;color:var(--muted)}.small{max-width:900px}.button{display:inline-block;border:1px solid var(--red);padding:9px 16px;text-decoration:none;margin:15px 12px 0 0;font-size:14px}.thumbs{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin:50px 0 0}.thumbs a{text-decoration:none}.thumbs img{width:100%;height:auto;display:block}.thumbs span{font:20px/1.2 Georgia,serif;display:block;margin-top:12px}.plate{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(270px,1fr);gap:45px;border-top:1px solid var(--line);padding:55px 0 70px;scroll-margin-top:25px}figure{margin:0}figure img{display:block;width:100%;height:auto}figcaption{margin-top:10px}.notes{padding-top:60px}.notes article{padding:0 0 22px;margin-bottom:25px;border-bottom:1px solid var(--line)}.notes p{margin:8px 0}.caption{font:22px/1.3 Georgia,serif}.notes article>p:not(.caption){font-size:14px}.notes details{font-size:13px;color:var(--muted)}summary{cursor:pointer;text-decoration:underline;text-underline-offset:3px}.reading{max-width:840px;margin:20px auto 65px}.reading p{font-size:18px}.reading .small{font-size:13px}.reading blockquote{border-left:2px solid var(--red);padding-left:22px;font:29px/1.4 Georgia,serif;margin:35px 0}.sources{margin-top:35px;border-top:1px solid var(--line);padding-top:25px}footer{border-top:1px solid var(--line);font-size:13px;color:var(--muted)}@media(max-width:850px){header,main,footer{padding:24px}.thumbs{grid-template-columns:repeat(2,1fr)}.plate{grid-template-columns:1fr;gap:20px}.notes{padding-top:0;display:grid;grid-template-columns:repeat(2,1fr);gap:20px}h2{font-size:30px}}@media(max-width:500px){.notes{grid-template-columns:1fr}.lead{font-size:22px}}@media print{.thumbs,.button{display:none}.plate{display:block;break-before:page;padding:0}.plate img{height:245mm;width:auto;max-width:100%;margin:auto}.notes{display:none}h2{font-size:20px;margin:10px 0}.reading{break-before:page}header{padding-top:10px}}
</style></head><body><header><p class="eyebrow">Endless Museum / Forces and beyond / 7 October 2026</p><h1>The dark side of<br><em>The Nature of Code</em></h1><p class="lead">The error is a room you cannot enter, a floor that no longer supports you, a rule that keeps returning you to the same place. The student still holds the point.</p><p class="small">Sixteen physical situations in four comic plates. An original artistic response: selected HTTP statuses, programming failures and simulation problems become museum encounters. These images are proposals, not native museum captures, implemented behaviors or an exhaustive catalogue of software errors.</p><a class="button" href="physical-errors.zip">Download the four plates</a><a class="button" href="#reading">The idea</a><div class="thumbs">'''+thumbs+'''</div></header><main>'''+sections+'''<article class="reading" id="reading"><p class="eyebrow">A possible underside of the curriculum</p><h2>What does the rule make you live through?</h2><p>Earlier, the point gave the student a way to act. Here the surrounding system exposes the conditions of that ability. The point still fits the hand when an intake rejects it. An address can remain legible after its destination disappears. A repeated operation can consume all the room left for a body.</p><blockquote>The next room exists.<br>The next room is forbidden.<br>The next room is this room again.</blockquote><p>These encounters could return beside the concepts they trouble: an absent reference beside the point; a missing cell beside the grid; unreleased copies beside arrays; recursive frames beside recursion; lost collisions and excessive corrections beside forces. They do not need to become a separate lesson in every hall. A single encounter can interrupt the confidence of an operation we thought we understood.</p><p>The political opening is in the difference between failure and refusal. A locked entrance may be performing its assigned job perfectly. That does not settle whether the rule should be there. Similarly, a boundary can protect a body or exclude it; its meaning depends on what the boundary does, to whom, and under whose control.</p><p>The physical comedy remains available. But we can stay with the missing handle, the overloaded storage and the impossible exchange long enough to feel frustration and dependence as well as the joke. The student might diagnose, wait, ask for help, find another use or challenge the rule.</p><p class="small">If developed in Godot, build bounded encounters with a way out rather than deliberately hanging or exhausting the actual application. A simulated failure can be an artifact without making the research environment unusable. None of these images proves the corresponding behavior is present or physically stable.</p><div class="sources"><h3>Terms and limits</h3><p class="small">403 is a refusal after a request is understood; 404 can mean no representation was found or that existence is not disclosed; 408 concerns an incomplete request not received in time. The architecture is an artistic translation of those distinctions. <a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-15.5">RFC 9110</a>.</p><p class="small">429 concerns request frequency. Adding weight to a lock is our invented physical consequence. <a href="https://www.rfc-editor.org/rfc/rfc6585.html#section-4">RFC 6585, section 4</a>.</p><p class="small">The collision and instability plates draw on actual simulation concerns, but their dramatic outcomes are invented. Godot documents limitations involving fast bodies and thin barriers, and options for continuous collision detection. <a href="https://docs.godotengine.org/en/stable/tutorials/physics/troubleshooting_physics_issues.html">Physics troubleshooting</a> · <a href="https://docs.godotengine.org/en/stable/classes/class_rigidbody3d.html#class-rigidbody3d-property-continuous-cd">RigidBody3D continuous collision detection</a>.</p><p class="small">The division-by-zero device is symbolic: a zero distance alone is not a division operation. A tutorial would need to show the actual formula and its handling. Likewise, shape mismatch, nested doorframes and locked cases are analogies, not exact implementations of types, call stacks or concurrent processes.</p></div></article></main><footer>Built-in OpenAI image generation. <a href="atlas.json">Editable situations, explanations, complete prompts and image origins</a> · <a href="../2026-10-07-forces-fail-shorts/index.html">Previous fail shorts</a> · <a href="../2026-10-07-forces-the-unintended/index.html">The world plays out</a>. Museum runtime and canonical manuscripts are unchanged.</footer></body></html>'''
(OUT/'index.html').write_text(html,encoding='utf-8')

class Links(HTMLParser):
    def __init__(self): super().__init__(); self.urls=[]; self.ids=set()
    def handle_starttag(self,tag,attrs):
        a=dict(attrs)
        if 'id' in a:self.ids.add(a['id'])
        self.urls.extend(a[k] for k in ('src','href') if k in a)
p=Links();p.feed(html)
for link in p.urls:
    u=urlsplit(link)
    if u.scheme:continue
    if not u.path:assert u.fragment in p.ids,link
    elif not u.path.endswith('.zip'):assert (OUT/u.path).is_file(),link
with zipfile.ZipFile(OUT/'physical-errors.zip','w',zipfile.ZIP_DEFLATED) as z:
    for f in OUT.rglob('*'):
        if f.is_file() and f.suffix!='.zip' and '__pycache__' not in f.parts:z.write(f,f.relative_to(OUT))
with zipfile.ZipFile(OUT/'physical-errors.zip') as z:assert z.testzip() is None
print(json.dumps({'plates':dimensions,'situations':sum(len(p['items']) for p in data['plates']),'links_checked':len(p.urls),'zip':'CRC passed','page':str(OUT/'index.html')}))
